describe('Homepage Hero Section', () => {
    beforeEach(() => {
        cy.visit('/');
    });

    it('should display the hero section correctly on mobile', () => {
        cy.viewport('iphone-6'); // Set viewport to mobile size
        cy.get('.hero-section').should('be.visible');
        cy.get('.hero-title').should('have.css', 'font-size', '24px'); // Example check for font size
        cy.get('.hero-image').should('have.attr', 'src').and('include', 'mobile-hero-image.jpg'); // Check for mobile image
    });

    it('should not display the desktop hero image on mobile', () => {
        cy.viewport('iphone-6'); // Set viewport to mobile size
        cy.get('.hero-image').should('not.have.attr', 'src', 'desktop-hero-image.jpg'); // Ensure desktop image is not displayed
    });
});
